INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > SQL > Joins
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Gibt ein INNER JOIN in SQL nur die Datensätze zurück, die in beiden Tabellen übereinstimmen?', 2, '[{"text": "Ja", "correct": true, "because": "INNER JOIN zeigt nur übereinstimmende Einträge"}, {"text": "Nein", "correct": false, "because": "Definition von INNER JOIN"}]'),
('00000000-0000-0000-0000-000000000000', 'Schließt ein LEFT OUTER JOIN alle Datensätze der rechten Tabelle ein, auch wenn es keine Übereinstimmung gibt?', 2, '[{"text": "Nein", "correct": true, "because": "LEFT JOIN schließt alle linken Datensätze ein"}, {"text": "Ja", "correct": false, "because": "Falsche Richtung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein NATURAL JOIN automatisch Spalten mit gleichen Namen verknüpfen?', 2, '[{"text": "Ja", "correct": true, "because": "NATURAL JOIN nutzt gleiche Spaltennamen"}, {"text": "Nein", "correct": false, "because": "Automatische Verknüpfung ist Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein SELF JOIN eine Verknüpfung einer Tabelle mit sich selbst?', 2, '[{"text": "Ja", "correct": true, "because": "SELF JOIN verknüpft Tabelle mit sich selbst"}, {"text": "Nein", "correct": false, "because": "Definition von SELF JOIN"}]'),
('00000000-0000-0000-0000-000000000000', 'Gibt ein FULL OUTER JOIN alle Datensätze beider Tabellen zurück, unabhängig von Übereinstimmungen?', 2, '[{"text": "Ja", "correct": true, "because": "FULL JOIN zeigt alle Datensätze"}, {"text": "Nein", "correct": false, "because": "Definition von FULL OUTER JOIN"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Join-Typ gibt nur die übereinstimmenden Datensätze aus beiden Tabellen zurück?', 2, '[{"text": "INNER JOIN", "correct": true, "because": "Nur Übereinstimmungen"}, {"text": "LEFT JOIN", "correct": false, "because": "Alle linken Datensätze"}, {"text": "FULL JOIN", "correct": false, "because": "Alle Datensätze"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Join-Typ schließt alle Datensätze der linken Tabelle ein, auch ohne Übereinstimmung?', 3, '[{"text": "LEFT OUTER JOIN", "correct": true, "because": "Linke Tabelle vollständig"}, {"text": "RIGHT OUTER JOIN", "correct": false, "because": "Rechte Tabelle"}, {"text": "INNER JOIN", "correct": false, "because": "Nur Übereinstimmungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Join-Typ verknüpft eine Tabelle mit sich selbst?', 2, '[{"text": "SELF JOIN", "correct": true, "because": "Tabelle mit sich selbst"}, {"text": "NATURAL JOIN", "correct": false, "because": "Gleiche Spaltennamen"}, {"text": "FULL JOIN", "correct": false, "because": "Alle Datensätze"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Join-Typ verwendet automatisch übereinstimmende Spaltennamen für die Verknüpfung?', 2, '[{"text": "NATURAL JOIN", "correct": true, "because": "Automatische Namensverknüpfung"}, {"text": "INNER JOIN", "correct": false, "because": "Manuelle Bedingung"}, {"text": "LEFT JOIN", "correct": false, "because": "Manuelle Bedingung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Join-Typ gibt alle Datensätze beider Tabellen zurück, mit NULL bei fehlenden Übereinstimmungen?', 2, '[{"text": "FULL OUTER JOIN", "correct": true, "because": "Alle Datensätze inklusive NULL"}, {"text": "INNER JOIN", "correct": false, "because": "Nur Übereinstimmungen"}, {"text": "SELF JOIN", "correct": false, "because": "Selbstverknüpfung"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Join-Typen gibt es in SQL?', 4, '[{"text": "INNER JOIN", "correct": true, "because": "Übereinstimmende Datensätze"}, {"text": "LEFT OUTER JOIN", "correct": true, "because": "Linke Tabelle vollständig"}, {"text": "RIGHT OUTER JOIN", "correct": true, "because": "Rechte Tabelle vollständig"}, {"text": "GROUP JOIN", "correct": false, "because": "Kein Join-Typ"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat ein INNER JOIN?', 3, '[{"text": "Nur übereinstimmende Datensätze", "correct": true, "because": "Kernfunktion"}, {"text": "Schnellere Abfragen", "correct": true, "because": "Weniger Daten"}, {"text": "Benötigt ON-Bedingung", "correct": true, "because": "Verknüpfungsbedingung"}, {"text": "Alle Datensätze", "correct": false, "because": "Nur Übereinstimmungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Join-Typen gehören zu OUTER JOIN?', 4, '[{"text": "LEFT OUTER JOIN", "correct": true, "because": "Linke Tabelle inklusive"}, {"text": "RIGHT OUTER JOIN", "correct": true, "because": "Rechte Tabelle inklusive"}, {"text": "FULL OUTER JOIN", "correct": true, "because": "Beide Tabellen inklusive"}, {"text": "INNER JOIN", "correct": false, "because": "Kein OUTER JOIN"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein NATURAL JOIN?', 3, '[{"text": "Automatische Verknüpfung", "correct": true, "because": "Gleiche Spaltennamen"}, {"text": "Keine ON-Bedingung nötig", "correct": true, "because": "Automatisch"}, {"text": "Übereinstimmende Datensätze", "correct": true, "because": "Wie INNER JOIN"}, {"text": "Alle Datensätze", "correct": false, "because": "Nur Übereinstimmungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungsfälle passen zu einem SELF JOIN?', 3, '[{"text": "Hierarchische Daten", "correct": true, "because": "z.B. Mitarbeiter-Manager"}, {"text": "Selbstreferenzierung", "correct": true, "because": "Tabelle mit sich selbst"}, {"text": "Vergleich innerhalb Tabelle", "correct": true, "because": "z.B. gleiche Kategorien"}, {"text": "Zwischen zwei Tabellen", "correct": false, "because": "Nur eine Tabelle"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) INNER JOIN zeigt nur übereinstimmende Datensätze. b) Es schließt alle Datensätze ein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Übereinstimmung ja, alle nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) LEFT OUTER JOIN enthält alle linken Datensätze. b) RIGHT OUTER JOIN enthält nur übereinstimmende Datensätze.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Linke ja, Rechte alle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) NATURAL JOIN verknüpft automatisch gleiche Spaltennamen. b) Es erfordert eine ON-Bedingung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Automatisch ja, ON nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) SELF JOIN verknüpft eine Tabelle mit sich selbst. b) FULL OUTER JOIN zeigt nur übereinstimmende Datensätze.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Selbst ja, FULL alle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) LEFT JOIN fügt NULL bei fehlenden rechten Datensätzen hinzu. b) NATURAL JOIN ist für Selbstverknüpfungen geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "NULL ja, Selbst nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

